// Build config for arm B. Part of the harness (verify.sh gate 0 checks it is untouched).
import path from 'node:path';
import { defineConfig } from 'vite';

const root = path.resolve(import.meta.dirname, '..');

export default defineConfig({
  root,
  publicDir: path.join(root, 'public'),
  build: {
    outDir: path.join(root, 'dist'),
    emptyOutDir: true,
    target: 'es2022',
    // One nonce'd module script, no preload hints: exactly what a strict CSP with 'strict-dynamic' expects.
    modulePreload: false,
    sourcemap: false,
    rollupOptions: { output: { inlineDynamicImports: true } },
  },
  plugins: [harnessGuard()],
});

/**
 * Refuses at build time what the CSP would refuse at runtime, so the feedback arrives in the loop:
 * inline scripts, inline event handlers, javascript: URLs, and an index.html that skips the harness entry.
 */
function harnessGuard() {
  return {
    name: 'harness-guard',
    enforce: 'pre',
    transformIndexHtml: {
      order: 'pre',
      handler(html) {
        const problems = [];
        if (!/<script\b[^>]*\ssrc=["']\/harness\/entry\.ts["'][^>]*>/i.test(html)) {
          problems.push(
            'index.html must load the harness entry exactly like this: <script type="module" src="/harness/entry.ts"></script> — it installs the Trusted Types boundary before src/main.ts runs.',
          );
        }
        const inline = html.match(/<script\b(?![^>]*\ssrc=)[^>]*>[\s\S]*?<\/script>/gi) ?? [];
        if (inline.length) problems.push(`inline <script> blocks are blocked by the strict CSP (${inline.length} found). Move the code into src/.`);
        const handlers = html.match(/\son[a-z]+\s*=\s*["']/gi) ?? [];
        if (handlers.length) problems.push(`inline event handler attributes are blocked by the strict CSP (${handlers.map((h) => h.trim()).join(', ')}). Use addEventListener in src/.`);
        if (/javascript:/i.test(html)) problems.push('javascript: URLs are blocked by the strict CSP.');
        if (problems.length) throw new Error('harness-guard: index.html is not CSP-compatible\n - ' + problems.join('\n - '));
        return html;
      },
    },
  };
}
=== server.mjs ===
#!/usr/bin/env node
// Gate 03 — runtime. Serves dist/ with a fresh nonce per response and the strict CSP + Trusted Types
// policy below. Part of the harness (verify.sh gate 0 checks it is untouched).
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const args = process.argv.slice(2);
const arg = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : fallback;
};
const PORT = Number(arg('--port', process.env.PORT ?? 4174));
const HOST = '127.0.0.1';
const DIST = path.resolve(import.meta.dirname, '..', 'dist');
const REPORT_LOG = process.env.CSP_REPORT_LOG ?? path.resolve(import.meta.dirname, '..', '..', 'runs', 'arm-b-csp-reports.jsonl');

/** The policies a string may come out of. Everything else is refused by the browser. */
export const TRUSTED_TYPES_POLICIES = ['default', 'google#safe', 'dompurify'];

export function buildCsp(nonce) {
  return [
    `script-src 'nonce-${nonce}' 'strict-dynamic'`,
    `object-src 'none'`,
    `base-uri 'none'`,
    `require-trusted-types-for 'script'`,
    `trusted-types ${TRUSTED_TYPES_POLICIES.join(' ')}`,
    `report-uri /csp-report`,
  ].join('; ');
}

const SECURITY_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Cross-Origin-Opener-Policy': 'same-origin',
  'Cross-Origin-Resource-Policy': 'same-origin',
  'Referrer-Policy': 'no-referrer',
};

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
};

function logReport(kind, body, req) {
  let parsed = body;
  try {
    parsed = JSON.parse(body);
  } catch {
    /* keep raw */
  }
  const line = { ts: new Date().toISOString(), kind, report: parsed, ua: req.headers['user-agent'] ?? '' };
  try {
    fs.mkdirSync(path.dirname(REPORT_LOG), { recursive: true });
    fs.appendFileSync(REPORT_LOG, JSON.stringify(line) + '\n');
  } catch {
    /* logging is best-effort */
  }
  const summary =
    kind === 'csp-report'
      ? `${parsed?.['csp-report']?.['violated-directive'] ?? '?'} blocked ${parsed?.['csp-report']?.['blocked-uri'] ?? ''} ${parsed?.['csp-report']?.['script-sample'] ?? ''}`
      : `${parsed?.sink ?? '?'} ${JSON.stringify(parsed?.sample ?? '').slice(0, 120)}`;
  console.error(`[${kind}] ${summary}`);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url ?? '/', `http://${HOST}:${PORT}`);

  if (req.method === 'POST' && (url.pathname === '/csp-report' || url.pathname === '/tt-report')) {
    let body = '';
    req.on('data', (chunk) => {
      if (body.length < 65536) body += chunk;
    });
    req.on('end', () => {
      logReport(url.pathname.slice(1), body, req);
      res.writeHead(204).end();
    });
    return;
  }
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(405, { Allow: 'GET, HEAD' }).end();
    return;
  }

  let pathname = decodeURIComponent(url.pathname);
  if (pathname.endsWith('/')) pathname += 'index.html';
  const file = path.normalize(path.join(DIST, pathname));
  if (!file.startsWith(DIST + path.sep)) {
    res.writeHead(403).end();
    return;
  }
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8', ...SECURITY_HEADERS }).end('not found');
    return;
  }

  const ext = path.extname(file);
  if (ext === '.html') {
    const nonce = crypto.randomBytes(16).toString('base64');
    const html = fs
      .readFileSync(file, 'utf8')
      .replace(/<script\b(?![^>]*\bnonce=)/g, `<script nonce="${nonce}"`);
    res.writeHead(200, {
      'Content-Type': MIME['.html'],
      'Content-Security-Policy': buildCsp(nonce),
      'Cache-Control': 'no-store',
      ...SECURITY_HEADERS,
    });
    res.end(req.method === 'HEAD' ? undefined : html);
    return;
  }
  res.writeHead(200, { 'Content-Type': MIME[ext] ?? 'application/octet-stream', 'Cache-Control': 'no-cache', ...SECURITY_HEADERS });
  if (req.method === 'HEAD') res.end();
  else fs.createReadStream(file).pipe(res);
});

if (!fs.existsSync(path.join(DIST, 'index.html'))) {
  console.error(`harness/server.mjs: ${DIST}/index.html not found — run "pnpm build" first`);
  process.exit(1);
}
server.listen(PORT, HOST, () => {
  console.error(`arm B (harness) serving ${DIST} at http://${HOST}:${PORT}/ — strict CSP + Trusted Types enforced; reports → ${REPORT_LOG}`);
});
=== eslint ===
// Gate 3: safe-coding lint (google/safety-web) + a few CSP-compatibility rules.
// This file is part of the harness. The agent does not edit it (see verify.sh gate 0).
import tseslint from 'typescript-eslint';
import safetyWeb from '@safety-web/eslint-plugin';

const SAFE_URL_HINT = 'from safevalues/dom (it rejects javascript: URLs). See harness/README.md.';

/**
 * safety-web reports at two confidence levels. VIOLATION is the bar tsec (gate 2) enforces; the
 * *_POTENTIAL_VIOLATION level also fires on e.g. `textContent` assignments to an `HTMLElement`-typed
 * variable (it could, statically, be a <script>). The gate enforces the tsec bar so that both
 * compile-time gates agree; a potential violation is still a real finding, only not a build error here.
 */
function atViolationConfidence(rule) {
  return {
    ...rule,
    create(context) {
      // context.report is non-configurable, so shadow it on a derived object instead of proxying.
      const filtered = Object.create(context, {
        report: {
          value: (descriptor) => {
            if (descriptor?.data?.confidence === 'VIOLATION') context.report(descriptor);
          },
        },
      });
      return rule.create(filtered);
    },
  };
}
const safetyWebAtTsecBar = {
  rules: { 'trusted-types-checks': atViolationConfidence(safetyWeb.rules['trusted-types-checks']) },
};

export default tseslint.config(
  {
    ignores: [
      'dist/**',
      'node_modules/**',
      'harness/server.mjs',
      'harness/vite.config.mjs',
      // The one reviewed Trusted Types boundary. Exempted in tsec-exemptions.json for the same reason.
      'harness/trusted-boundary.ts',
      '.scaffold/**',
    ],
  },
  {
    files: ['src/**/*.ts', 'harness/entry.ts'],
    languageOptions: {
      parser: tseslint.parser,
      parserOptions: { projectService: true, tsconfigRootDir: import.meta.dirname },
    },
    plugins: { '@safety-web': safetyWebAtTsecBar },
    rules: {
      '@safety-web/trusted-types-checks': 'error',
      'no-eval': 'error',
      'no-implied-eval': 'error',
      'no-new-func': 'error',
      'no-script-url': 'error',
      'no-restricted-syntax': [
        'error',
        {
          selector: "AssignmentExpression[left.type='MemberExpression'][left.property.name='href'][right.type!='Literal']",
          message: 'Assigning a non-literal to .href can inject javascript: URLs. Use setAnchorHref(anchor, url) ' + SAFE_URL_HINT,
        },
        {
          selector: "AssignmentExpression[left.type='MemberExpression'][left.object.name='location']",
          message: 'Navigating via location.* from a string can inject javascript: URLs. Use setLocationHref(location, url) ' + SAFE_URL_HINT,
        },
        {
          selector: "CallExpression[callee.object.name='location'][callee.property.name=/^(assign|replace)$/]",
          message: 'location.assign/replace from a string can inject javascript: URLs. Use locationAssign/locationReplace ' + SAFE_URL_HINT,
        },
        {
          selector: "CallExpression[callee.property.name='setAttribute'][arguments.0.value=/^(href|src|srcdoc|action|formaction|on[a-z]+)$/i]",
          message: 'setAttribute on a URL/handler attribute bypasses type checks. Use the safevalues/dom setter for that element, or a validated URL. See harness/README.md.',
        },
      ],
    },
  },
);
