:root {
  --bg: #f6f5f2;
  --surface: #ffffff;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #e0dcd5;
  --accent: #0f766e;
  --accent-soft: #ccfbf1;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 46rem;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
  display: grid;
  gap: 1.5rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.app-tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.note-form,
.search-panel,
.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1rem 1.25rem 1.25rem;
}

.form-heading {
  margin: 0 0 0.75rem;
  font-size: 1.1rem;
}

.field {
  display: grid;
  gap: 0.35rem;
  margin-bottom: 0.9rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0.5rem 0.6rem;
  width: 100%;
}

textarea {
  resize: vertical;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

button.primary {
  font: inherit;
  font-weight: 600;
  color: #ffffff;
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 0.5rem 1.1rem;
  cursor: pointer;
}

button.primary:hover {
  background: #115e56;
}

.search-panel .field {
  margin-bottom: 0.5rem;
}

.results-line {
  margin: 0;
  min-height: 1.4em;
  color: var(--muted);
  font-size: 0.9rem;
}

.feed {
  display: grid;
  gap: 1rem;
}

.note[aria-current='true'] {
  border-color: var(--accent);
  box-shadow: inset 4px 0 0 var(--accent);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--accent-soft);
  flex: none;
}

.note-heading {
  margin: 0;
  font-size: 1.15rem;
}

button.note-title {
  font: inherit;
  font-weight: 700;
  color: inherit;
  background: none;
  border: 0;
  border-radius: 6px;
  padding: 0;
  text-align: left;
  cursor: pointer;
}

button.note-title:hover {
  color: var(--accent);
  text-decoration: underline;
}

.note-body {
  margin: 0.6rem 0 0;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-meta {
  margin: 0.7rem 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.feed-empty {
  margin: 0;
  padding: 1rem 0;
  color: var(--muted);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #171614;
    --surface: #211f1c;
    --ink: #f5f3ef;
    --muted: #a8a29e;
    --line: #3a3733;
    --accent: #5eead4;
    --accent-soft: #134e4a;
    color-scheme: dark;
  }

  button.primary {
    color: #06231f;
  }

  button.primary:hover {
    background: #2dd4bf;
  }
}

