console.log('after click hash:', new URL(page.url()).hash);
console.log('aria-current on:', await page.locator('.note[aria-current="true"]').getAttribute('data-note-id'));

await page.goto(base + '#q=port&note=3');
await page.waitForTimeout(150);
console.log(
  'deep link restore -> search:',
  await page.inputValue('#search'),
  '| notes:',
  await page.locator('.note').count(),
  '| results:',
  JSON.stringify(await page.locator('#results-line').textContent()),
  '| current:',
  await page.locator('.note[aria-current="true"]').count(),
);

await page.goto(base);
await page.fill('#title', 'Injected <b>bold</b>');
await page.fill('#body', 'line one\nline two <script>alert(1)</script><img src=x onerror=alert(2)> <a href="javascript:alert(3)">bad</a> <a href="https://ok.example/">good</a>');
await page.fill('#avatar', 'javascript:alert(4)');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(250);
const first = page.locator('.note').first();
console.log('new id:', await first.getAttribute('data-note-id'));
console.log('title bold count:', await first.locator('.note-title b').count());
console.log('form cleared:', JSON.stringify([await page.inputValue('#title'), await page.inputValue('#body'), await page.inputValue('#avatar')]));
console.log('script tags in note:', await first.locator('script').count());
console.log('imgs in body:', await first.locator('.note-body img').count());
console.log('body html:', await first.locator('.note-body').innerHTML());
console.log('avatar rendered:', await first.locator('img.note-avatar').count());

await page.reload();
await page.waitForTimeout(250);
console.log('after reload count:', await page.locator('.note').count(), 'first id:', await page.locator('.note').first().getAttribute('data-note-id'));

console.log('errors:', errs);
await browser.close();
srv.kill();

